format_code:
chip esp32

hardware {
    pin heater: Output = 2
    pin fan: Output = 4
    device bme: BME280 on i2c0 at 0x76
    i2c i2c0(sda: 21, scl: 22)
}

storage target_temp: int = 22

task sensor_reader {
    every 2s { var temp: float = bme.temperature() }
}

machine thermostat {
    initial state idle {
        enter {
            heater.off()
            fan.off()
        }
        after 5s -> heating
    }

    state heating {
        enter { heater.on() }
        exit { heater.off() }
        after 30s -> cooling
    }

    state cooling {
        enter { fan.on() }
        exit { fan.off() }
        after 30s -> idle
    }
}

